const ajv = new Ajv2020({ strict: true, strictRequired: false, allErrors: false, passContext: true });
// JSON Schema operates on values, not tokens. This private keyword preserves the
// wire rule that integer fields cannot use a decimal point or exponent spelling.
ajv.addKeyword({
  keyword: "wireInteger", schemaType: "boolean",
  validate: function(this: { nonIntegers: Set<string> }, _rule: boolean, _value: unknown,
                     _parent: unknown, context?: { instancePath: string }) {
    return !this.nonIntegers.has(context?.instancePath ?? "");
  },
});
function wireSchema(node: unknown): unknown {
  if (Array.isArray(node)) return node.map(wireSchema);
  if (node !== null && typeof node === "object") {
    const result = Object.fromEntries(Object.entries(node).map(([k, v]) => [k, wireSchema(v)]));
    if (result.type === "integer") result.wireInteger = true;
    return result;
  }
  return node;
}
