/** Validate at every wire boundary; TS interfaces alone do not validate JSON. */
export function validate<K extends keyof Records>(name: K, value: unknown,
    nonIntegers: Set<string> = new Set()): asserts value is Records[K] {
  const validator = ajv.getSchema(`${schemaDocument.$id}#/$defs/${name}`);
  if (!validator) throw new Error(`Unknown schema: ${name}`);
  if (!validator.call({ nonIntegers }, value)) throw new Error(`Invalid ${name}: ${ajv.errorsText(validator.errors)}`);
}

export function decode<K extends keyof Records>(name: K, json: string): Records[K] {
  const { value, nonIntegers } = parseWireJSON(json);
  validate(name, value, nonIntegers);
  return value;
}

export function encode<K extends keyof Records>(name: K, value: Records[K]): string {
  validate(name, value);
  const json = JSON.stringify(value);
  // Reject constructed strings containing lone surrogates as well as wire input.
  const parsed = parseWireJSON(json);
  validate(name, parsed.value, parsed.nonIntegers);
  return json;
}

/** Parse before native object decoding can discard duplicate keys or number spelling. */
